const { DatabaseSync } = require('node:sqlite')
const db = new DatabaseSync(require('os').homedir() + '/.omniroute/storage.sqlite', { readOnly: true })
const tables = db.prepare("select name from sqlite_master where type='table'").all().map(r => r.name)
console.log(tables.join(' '))
for (const t of tables.filter(n => /log|request|usage|call/i.test(n))) {
  console.log('==', t, db.prepare(`select count(*) c from "${t}"`).get().c)
  console.log(db.prepare(`pragma table_info("${t}")`).all().map(c => c.name).join(','))
}
EOF
